function toListParam(values) {
    return values && values.length > 0 ? values : undefined;
}
export async function fetchApiProtocolStatsSummary(ctx, params) {
    return ctx.api.fetchJson("/v1/stats/summary", {
        query: {
            networks: toListParam(params?.networks),
            versions: toListParam(params?.versions),
        },
    });
}
export async function fetchApiProtocolStatsTimeseries(ctx, params) {
    return ctx.api.fetchJson("/v1/stats/timeseries", {
        query: {
            metric: params.metric,
            groupBy: params.groupBy,
            networks: toListParam(params.networks),
            versions: toListParam(params.versions),
            from: params.from,
            to: params.to,
        },
    });
}
export async function fetchApiProtocolStatsSources(ctx) {
    return ctx.api.fetchJson("/v1/stats/sources");
}
